import itertools, random
n=9
fixed={(0,8),(6,7)}
# try random graphs
for _ in range(20000):
    edges=set(fixed)
    # add random edges
    possible=[e for e in itertools.combinations(range(n),2) if e not in fixed]
    m=random.randint(12,17)
    # ensure we have at least len(fixed) edges
    if m< len(fixed): continue
    extra=random.sample(possible, m-len(fixed))
    edges.update(extra)
    # degree check
    deg=[0]*n
    for u,v in edges:
        deg[u]+=1;deg[v]+=1
    if min(deg)<2 or max(deg)>3:
        continue
    # chromatic number <=4 >=2 using simple greedy backtrack
    # try coloring with 4 colors
    colors=[-1]*n
    def dfs(v):
        if v==n:
            return True
        for c in range(4):
            ok=True
            for u in range(n):
                if (u,v) in edges or (v,u) in edges:
                    if colors[u]==c:
                        ok=False;break
            if ok:
                colors[v]=c
                if dfs(v+1):
                    return True
                colors[v]=-1
        return False
    if not dfs(0):
        continue
    # check not 1-colorable
    if len(set(colors))==1:
        continue
    print('found',edges,deg,colors)
    break
else:
    print('none')
